"use client";

import Image from "next/image";
import Link from "next/link";
import { FileText, LogOut, Menu, Moon, Shield, Sun, User } from "lucide-react";
import { usePathname } from "next/navigation";
import { useTheme } from "next-themes";
import { useEffect, useState } from "react";

import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { useDashboardShell } from "@/components/layout/dashboard-shell-provider";

type HeaderUser = {
  name: string;
  email: string;
  avatarUrl: string | null;
};

const breadcrumbLabels: Record<string, string> = {
  "/dashboard": "Dashboard",
  "/dashboard/mock-exams": "Mock Exams",
  "/dashboard/results": "Results",
  "/dashboard/materials": "Materials",
  "/dashboard/profile": "Profile",
};

export function DashboardHeader() {
  const pathname = usePathname();
  const { setOpen } = useDashboardShell();
  const { resolvedTheme, setTheme } = useTheme();
  const [mounted, setMounted] = useState(false);
  const [user, setUser] = useState<HeaderUser | null>(null);

  useEffect(() => {
    setMounted(true);

    let active = true;

    async function loadUser() {
      try {
        const response = await fetch("/api/auth/me");
        const result = (await response.json()) as {
          data?: {
            user?: {
              name: string;
              email: string;
              avatarUrl: string | null;
            };
          };
        };

        if (active && response.ok && result.data?.user) {
          setUser(result.data.user);
        }
      } catch {
        if (active) {
          setUser(null);
        }
      }
    }

    void loadUser();

    return () => {
      active = false;
    };
  }, []);

  const breadcrumbs = getBreadcrumbs(pathname);

  return (
    <header
      className="
        sticky top-0 z-30 w-full border-b border-border bg-card/95
        pl-0 backdrop-blur transition-[padding] duration-300 ease-in-out
        lg:pl-64
      "
    >
      <div className="flex h-16 items-center justify-between px-4 lg:px-6">
        <div className="flex min-w-0 items-center gap-4">
          <button
            type="button"
            aria-label="Open dashboard menu"
            onClick={() => setOpen(true)}
            className="
              flex h-9 w-9 cursor-pointer items-center justify-center rounded-md
              text-primary hover:bg-primary/5 focus-visible:outline-none
              focus-visible:ring-2 focus-visible:ring-accent
              focus-visible:ring-offset-2 focus-visible:ring-offset-background
              lg:hidden
            "
          >
            <Menu size={20} />
          </button>
          <Link
            href="/dashboard"
            className="font-heading text-base font-bold text-primary lg:hidden"
          >
            BJS Prep
          </Link>
          <nav
            aria-label="Breadcrumb"
            className="hidden min-w-0 items-center gap-2 truncate text-sm text-muted lg:flex"
          >
            {breadcrumbs.map((label, index) => (
              <span
                key={`${label}-${index}`}
                className="inline-flex items-center gap-2"
              >
                {index > 0 ? <span aria-hidden="true">/</span> : null}
                <span
                  className={
                    index === breadcrumbs.length - 1
                      ? "truncate font-medium text-foreground"
                      : "truncate"
                  }
                >
                  {label}
                </span>
              </span>
            ))}
          </nav>
        </div>

        <div className="flex items-center gap-2">
          {mounted ? (
            <button
              type="button"
              aria-label="Toggle theme"
              onClick={() =>
                setTheme(resolvedTheme === "dark" ? "light" : "dark")
              }
              className="
                flex h-9 w-9 cursor-pointer items-center justify-center rounded-md
                text-primary hover:bg-primary/5 focus-visible:outline-none
                focus-visible:ring-2 focus-visible:ring-accent
                focus-visible:ring-offset-2 focus-visible:ring-offset-background
              "
            >
              {resolvedTheme === "dark" ? (
                <Moon size={18} />
              ) : (
                <Sun size={18} />
              )}
            </button>
          ) : (
            <span className="h-9 w-9" aria-hidden="true" />
          )}

          <DropdownMenu>
            <DropdownMenuTrigger>
              <button
                type="button"
                aria-label="Open user menu"
                className="
                  flex h-9 w-9 cursor-pointer items-center justify-center
                  rounded-full text-primary hover:bg-primary/5
                  focus-visible:outline-none focus-visible:ring-2
                  focus-visible:ring-accent focus-visible:ring-offset-2
                  focus-visible:ring-offset-background
                "
              >
                <UserAvatar avatarUrl={user?.avatarUrl ?? null} />
              </button>
            </DropdownMenuTrigger>
            <DropdownMenuContent className="w-64 p-2">
              <div className="border-b border-border px-3 py-3">
                <p className="truncate text-sm font-medium text-foreground">
                  {user?.name ?? "Your account"}
                </p>
                <p className="truncate text-xs text-muted">
                  {user?.email ?? "Loading account details"}
                </p>
              </div>
              <MenuLink href="/dashboard/profile" icon={<User size={16} />}>
                Profile
              </MenuLink>
              <DropdownMenuSeparator />
              <MenuLink href="/terms" icon={<FileText size={16} />}>
                Terms
              </MenuLink>
              <MenuLink href="/privacy" icon={<Shield size={16} />}>
                Privacy
              </MenuLink>
              <DropdownMenuSeparator />
              <button
                type="button"
                onClick={logout}
                className="
                  flex min-h-9 w-full cursor-pointer items-center gap-3 rounded
                  px-3 py-2 text-left text-sm text-red-600 hover:bg-red-50
                  focus-visible:outline-none focus-visible:ring-2
                  focus-visible:ring-accent focus-visible:ring-offset-2
                "
              >
                <LogOut size={16} />
                Log out
              </button>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      </div>
    </header>
  );
}

function UserAvatar({ avatarUrl }: { avatarUrl: string | null }) {
  return avatarUrl ? (
    <Image
      src={avatarUrl}
      alt=""
      width={32}
      height={32}
      unoptimized
      className="h-8 w-8 rounded-full object-cover"
    />
  ) : (
    <span className="flex h-8 w-8 items-center justify-center rounded-full bg-primary/10 text-primary">
      <User size={18} />
    </span>
  );
}

function MenuLink({
  href,
  icon,
  children,
}: {
  href: string;
  icon: React.ReactNode;
  children: string;
}) {
  return (
    <Link
      href={href}
      className="
        flex min-h-9 cursor-pointer items-center gap-3 rounded px-3 py-2
        text-sm text-primary hover:bg-primary/5 focus-visible:outline-none
        focus-visible:ring-2 focus-visible:ring-accent
        focus-visible:ring-offset-2 focus-visible:ring-offset-background
      "
    >
      {icon}
      {children}
    </Link>
  );
}

function getBreadcrumbs(pathname: string) {
  if (
    pathname.startsWith("/dashboard/mock-exams/") &&
    pathname !== "/dashboard/mock-exams"
  ) {
    return ["Dashboard", "Mock Exams", "Take Test"];
  }

  return [
    breadcrumbLabels[pathname] ? "Dashboard" : "Dashboard",
    breadcrumbLabels[pathname] ?? "Dashboard",
  ].filter((label, index, items) => index === 0 || label !== items[0]);
}

async function logout() {
  try {
    await fetch("/api/auth/logout", { method: "POST" });
  } finally {
    window.location.href = "/login";
  }
}
